  /**
    The different types of corner closures that can be created.
    @experimental
    */
  export const enum CornerClosureTypes {
      /// The corner closure type is undefined. This occurs when the two input edges are
      /// independent and do not define a corner.
    UndefinedCornerClosureType,
      /// A two-bend corner closure that includes relief features for two-bend intersections.
    TwoBendCornerClosureType,
      /// A three-bend corner closure that handles three-bend intersections with advanced relief options.
    ThreeBendCornerClosureType,
  }

  /**
    Specifies the available alignment types for corner closures, determining how sheets are joined at a corner
    intersection.
    @experimental
    */
  export const enum CornerClosureAlignmentTypes {
      /// A symmetric gap alignment creates a corner closure with a gap that is symmetric about the corner intersection.
    SymmetricGapCornerClosureAlignmentType,
      /// An overlap alignment creates a corner closure where one sheet overlaps the other at the corner intersection.
      /// The amount of overlap is defined by the overlap value.
    OverlapCornerClosureAlignmentType,
  }

  /**
    The different bend transition types for corner closures.
    @experimental
    */
  export const enum BendTransitionTypes {
      /// Smooth bend transition.
    SmoothCornerBendTransitionType,
      /// Straight line bend transition.
    StraightLineCornerBendTransitionType,
      /// Trim to bend transition.
    TrimToBendCornerBendTransitionType,
  }

